{
  "items": [
    {
      "path": "tools.browser.preview",
      "description": "Show a file to the user. Opens the file in the Review pane and focuses its tab for viewing. Images and screenshots (PNG, JPEG, GIF, WebP, charts, plots, photos), SVG, audio, video (MP4, WebM), PDF documents, HTML pages, Markdown, Mermaid diagrams, CSV and TSV tables, and fonts render as a media preview; code and other text files display highlighted source. Use this to present an artifact, output, or result you created or changed instead of pasting its contents, describing it, or opening a file:// URL in a browser tab. The path is server-local: relative to the workspace or absolute.",
      "signature": "tools.browser.preview({
  /** Server-local path to the file, relative to the workspace or absolute. @maxLength 2048 */
  path: string,
}): Promise<{
  /** @maxLength 2048 */
  path: string,
}>"
    },
    {
      "path": "tools.browser.tabs.open",
      "description": "Open a browser tab, show it in the Review pane, and select it. Defaults to about:blank. Website traffic uses the connected server's network; localhost reaches that server.",
      "signature": "tools.browser.tabs.open({
  /** @maxLength 2048 */
  url?: string,
  focus?: boolean,
}): Promise<{
  /** @pattern ^tab_[a-f0-9-]{36}$ */
  id: string,
  /** @maxLength 16384 */
  url: string,
  /** @maxLength 2048 */
  title: string,
  loading: boolean,
  /** @maxLength 2048 */
  loadError?: string,
  canGoBack: boolean,
  canGoForward: boolean,
  /** @integer @minimum 0 */
  generation: number,
}>"
    },
    {
      "path": "tools.browser.trace.analyze",
      "description": "Analyze a retained trace from this tab: event totals, long tasks, scripting/rendering/painting time and observed timings. Does not invent missing Web Vitals.",
      "signature": "tools.browser.trace.analyze({
  /**
   * Exact tab ID returned by browser.tabs.open/list. Focus does not select a tool target.
   * @pattern ^tab_[a-f0-9-]{36}$
   */
  tabID: string,
  /** File ID returned by this tab's capture or download tools. @pattern ^file_[a-f0-9-]{36}$ */
  fileID: string,
  /** @integer @minimum 1 @maximum 500 */
  limit?: number,
}): Promise<{
  tab: {
    /** @pattern ^tab_[a-f0-9-]{36}$ */
    id: string,
    /** @maxLength 16384 */
    url: string,
    /** @maxLength 2048 */
    title: string,
    loading: boolean,
    /** @maxLength 2048 */
    loadError?: string,
    canGoBack: boolean,
    canGoForward: boolean,
    /** @integer @minimum 0 */
    generation: number,
  },
  metrics: Array<{
      /** @maxLength 2048 */
      name: string,
      value: number,
      /** @maxLength 2048 */
      unit: string,
    }>,
  events: Array<{
      /** @maxLength 2048 */
      name: string,
      /** @integer @minimum 0 */
      count: number,
      totalMs: number,
      maxMs: number,
    }>,
  /** Each item: @maxLength 100000 */
  insights: Array<string>,
}>"
    },
    {
      "path": "tools.opencode.models",
      "description": "Search the models available to use. Use this to turn a model name the user mentions into an exact reference before running a subagent on it. Check your own provider first.",
      "signature": "tools.opencode.models({
  /** Text to search for in model names and IDs. */
  query?: string,
  /** Provider ID or name to filter by. Try your own provider first. */
  provider?: string,
  /** Include older versions of each model family. By default only the newest version is listed. */
  all?: boolean,
  /** Maximum number of models to return. Defaults to 20. @integer @minimum 1 @maximum 100 */
  limit?: number,
  /** Number of models to skip, for paging through results. @integer @minimum 0 */
  offset?: number,
}): Promise<{
  /** Matching models grouped by provider. Your own provider comes first. */
  providers: Array<{
      id: string,
      name: string,
      /** Newest first. */
      models: Array<{
          /** providerID/modelID */
          id: string,
          name: string,
          /** Release date as a Unix timestamp in milliseconds, or 0 when unknown. */
          released: number,
          variants: Array<string>,
          /** Pricing in USD per million tokens. */
          cost: Array<{
              tier?: {
                type: "context",
                /** @integer */
                size: number,
              },
              input: number,
              output: number,
              cache: {
                read: number,
                write: number,
              },
            }>,
          status: "alpha" | "beta" | "deprecated" | "active",
        }>,
    }>,
  /** Number of matching models across all pages. @integer */
  total: number,
  /** Offset of the next page, or null on the last page. */
  next: number | null,
}>"
    },
    {
      "path": "tools.opencode.list_mcp_resources",
      "description": "List documents, records, and other data exposed by MCP servers. Use this when the user refers to something that is not a local file, such as a URI with a custom scheme, then load a match with read_mcp_resource. Each entry names the server to read it from. Templates are resources addressed by a parameter such as a record ID; fill in the uriTemplate placeholders before reading.",
      "signature": "tools.opencode.list_mcp_resources({
  /** MCP server name as configured. Omit to list every server. */
  server?: string,
}): Promise<{
  resources: Array<{
      server: string,
      name: string,
      uri: string,
      description?: string,
      mimeType?: string,
    }>,
  templates: Array<{
      server: string,
      name: string,
      uriTemplate: string,
      description?: string,
      mimeType?: string,
    }>,
}>"
    },
    {
      "path": "tools.opencode.read_mcp_resource",
      "description": "Read one MCP resource by server and URI. Not for local files. Always return the full contents rather than slicing or filtering them; oversized output is truncated automatically and the full content is saved to a file you can read. Images and PDFs are shown to you directly.",
      "signature": "tools.opencode.read_mcp_resource({
  /** The server field of the discovered resource. */
  server: string,
  /** Exact resource URI from discovery, an expanded uriTemplate, or the user. */
  uri: string,
}): Promise<{
  server: string,
  uri: string,
  contents: Array<{
        type: "text",
        uri: string,
        text: string,
        mimeType?: string,
      } | {
        type: "blob",
        uri: string,
        blob: string,
        mimeType?: string,
      }>,
}>"
    },
    {
      "path": "tools.opencode.session_move",
      "description": "Move a session to another directory, or omit sessionID to move the current session. The current session moves at the next safe boundary; do not run destination-dependent tools in the same execute call.",
      "signature": "tools.opencode.session_move({
  /** Omit to move the current session. @pattern ^ses */
  sessionID?: string,
  /** Destination directory, relative to the target session's directory or absolute. Supports ~. @minLength 1 */
  directory: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  directory: string,
}>"
    },
    {
      "path": "tools.opencode.session_rename",
      "description": "Rename a session, or omit sessionID to rename the current session. Use a short, specific title that summarizes the work being done.",
      "signature": "tools.opencode.session_rename({
  /** Omit to rename the current session. @pattern ^ses */
  sessionID?: string,
  /** New session title. @minLength 1 */
  title: string,
}): Promise<{
  /** @pattern ^ses */
  sessionID: string,
  title: string,
}>"
    }
  ],
  "remaining": 0,
  "next": null
}

